TASK
Memoize Promise-returning functions with configurable cache behavior.

PUBLIC CONTRACT
Module: await load('./index.js'); default export pMemoize (CommonJS), with pMemoize.clear.
pMemoize(fn, options?) returns a memoized version of a Promise-returning/async function. Calls with the same key reuse cached work/results. The default key is the first argument; cacheKey(argumentsArray) may select a custom key. Arguments and the receiver are passed to the original function. A custom cache may implement Map-style get, set, delete, and clear methods. maxAge is an integer duration in milliseconds; omitted maxAge retains results indefinitely, and expiry begins when the promise settles.
Rejected promises are not cached by default; cachePromiseRejection=true permits caching them. pMemoize.clear(memoized) clears cached data and rejects non-memoized functions or caches without a clear method. Preserve cached successes, error propagation, and configurable keys/cache behavior.

SOURCE index.js
   1: 'use strict';
   2: const mimicFn = require('mimic-fn');
   3: const mapAgeCleaner = require('map-age-cleaner');
   4: 
   5: const cacheStore = new WeakMap();
   6: 
   7: const pMemoize = (fn, {cachePromiseRejection = false, ...options} = {}) => {
   8: 	const {maxAge, cacheKey} = options;
   9: 	const cache = options.cache || new Map();
  10: 
  11: 	if (Number.isSafeInteger(maxAge)) {
  12: 		mapAgeCleaner(cache);
  13: 	} else if (typeof maxAge !== 'undefined') {
  14: 		throw new TypeError('maxAge is not a safe integer.');
  15: 	}
  16: 
  17: 	const memoized = async function (...arguments_) {
  18: 		const key = cacheKey ? cacheKey(arguments_) : arguments_[0];
  19: 
  20: 		const cacheItem = cache.get(key);
  21: 		if (cacheItem) {
  22: 			return cacheItem.data;
  23: 		}
  24: 
  25: 		const result = fn.apply(this, arguments_);
  26: 
  27: 		let resultError;
  28: 		try {
  29: 			return await Promise.resolve(result);
  30: 		} catch (error) {
  31: 			resultError = error;
  32: 			throw error;
  33: 		} finally {
  34: 			cache.set(key, {
  35: 				data: result,
  36: 				maxAge: maxAge ? Date.now() + maxAge : Number.POSITIVE_INFINITY
  37: 			});
  38: 
  39: 			if (!cachePromiseRejection && resultError) {
  40: 				cache.delete(key);
  41: 			}
  42: 		}
  43: 	};
  44: 
  45: 	mimicFn(memoized, fn);
  46: 	cacheStore.set(memoized, cache);
  47: 
  48: 	return memoized;
  49: };
  50: 
  51: module.exports = pMemoize;
  52: 
  53: module.exports.clear = memoized => {
  54: 	if (!cacheStore.has(memoized)) {
  55: 		throw new Error('Can\'t clear a function that was not memoized!');
  56: 	}
  57: 
  58: 	const cache = cacheStore.get(memoized);
  59: 
  60: 	if (typeof cache.clear !== 'function') {
  61: 		throw new TypeError('The cache Map can\'t be cleared!');
  62: 	}
  63: 
  64: 	cache.clear();
  65: };

